package com.careerguidance.config;
import com.careerguidance.entity.*; import com.careerguidance.repository.*; import org.springframework.boot.*; import org.springframework.core.annotation.Order; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.stereotype.Component; import java.util.*;
@Component @Order(2) public class DefaultAdminInitializer implements ApplicationRunner { private final UserRepository users; private final RoleRepository roles; private final PasswordEncoder passwords; public DefaultAdminInitializer(UserRepository u,RoleRepository r,PasswordEncoder p){users=u;roles=r;passwords=p;} public void run(ApplicationArguments args){if(users.existsByEmail("admin@careerai.com"))return;User u=new User();u.setFirstName("System");u.setLastName("Administrator");u.setEmail("admin@careerai.com");u.setPassword(passwords.encode("Admin@123"));u.setAccountStatus(AccountStatus.ACTIVE);u.setRoles(Set.of(roles.findByName(RoleName.ADMIN).orElseThrow()));users.save(u);System.out.println("Default administrator account initialized: admin@careerai.com");} }
